import React from 'react';
import Icon from '../../../components/AppIcon';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import { Checkbox } from '../../../components/ui/Checkbox';
import Button from '../../../components/ui/Button';

const FilterSidebar = ({ 
  filters, 
  onFilterChange, 
  onClearFilters, 
  isOpen, 
  onClose 
}) => {
  const categoryOptions = [
    { value: 'all', label: 'All Categories' },
    { value: 'scholarships', label: 'Scholarships' },
    { value: 'internships', label: 'Internships' },
    { value: 'jobs', label: 'Full-Time Jobs' },
    { value: 'competitions', label: 'Competitions' },
    { value: 'grants', label: 'Research Grants' },
    { value: 'fellowships', label: 'Fellowships' }
  ];

  const locationOptions = [
    { value: 'all', label: 'All Locations' },
    { value: 'remote', label: 'Remote' },
    { value: 'usa', label: 'United States' },
    { value: 'uk', label: 'United Kingdom' },
    { value: 'canada', label: 'Canada' },
    { value: 'europe', label: 'Europe' },
    { value: 'asia', label: 'Asia' },
    { value: 'global', label: 'Global' }
  ];

  const deadlineOptions = [
    { value: 'all', label: 'All Deadlines' },
    { value: 'week', label: 'Within 1 Week' },
    { value: 'month', label: 'Within 1 Month' },
    { value: 'quarter', label: 'Within 3 Months' },
    { value: 'open', label: 'Rolling/Open' }
  ];

  const eligibilityOptions = [
    { label: 'Undergraduate Students', value: 'undergraduate' },
    { label: 'Graduate Students', value: 'graduate' },
    { label: 'Recent Graduates', value: 'recent_grad' },
    { label: 'Early Career Professionals', value: 'early_career' },
    { label: 'International Applicants', value: 'international' },
    { label: 'No Experience Required', value: 'no_experience' }
  ];

  const fundingOptions = [
    { label: 'Fully Funded', value: 'fully_funded' },
    { label: 'Partially Funded', value: 'partially_funded' },
    { label: 'Paid Position', value: 'paid' },
    { label: 'Stipend Included', value: 'stipend' }
  ];

  return (
    <>
      {/* Mobile Overlay */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}
      {/* Sidebar */}
      <aside 
        className={`
          fixed lg:sticky top-16 left-0 h-[calc(100vh-4rem)] w-80 
          bg-card border-r border-border overflow-y-auto z-50
          transition-transform duration-300 ease-in-out
          ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}
      >
        <div className="p-4 md:p-6">
          {/* Header */}
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <Icon name="SlidersHorizontal" size={20} color="var(--color-primary)" />
              <h2 className="text-lg font-semibold text-primary">Filters</h2>
            </div>
            <button
              onClick={onClose}
              className="lg:hidden p-2 hover:bg-muted rounded-lg transition-colors"
              aria-label="Close filters"
            >
              <Icon name="X" size={20} />
            </button>
          </div>

          {/* Search */}
          <div className="mb-6">
            <Input
              type="search"
              placeholder="Search opportunities..."
              value={filters?.search}
              onChange={(e) => onFilterChange('search', e?.target?.value)}
              className="mb-4"
            />
          </div>

          {/* Category */}
          <div className="mb-6">
            <Select
              label="Category"
              options={categoryOptions}
              value={filters?.category}
              onChange={(value) => onFilterChange('category', value)}
            />
          </div>

          {/* Location */}
          <div className="mb-6">
            <Select
              label="Location"
              options={locationOptions}
              value={filters?.location}
              onChange={(value) => onFilterChange('location', value)}
              searchable
            />
          </div>

          {/* Deadline */}
          <div className="mb-6">
            <Select
              label="Deadline"
              options={deadlineOptions}
              value={filters?.deadline}
              onChange={(value) => onFilterChange('deadline', value)}
            />
          </div>

          {/* Eligibility */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-foreground mb-3">
              Eligibility
            </label>
            <div className="space-y-2">
              {eligibilityOptions?.map((option) => (
                <Checkbox
                  key={option?.value}
                  label={option?.label}
                  checked={filters?.eligibility?.includes(option?.value)}
                  onChange={(e) => {
                    const newEligibility = e?.target?.checked
                      ? [...filters?.eligibility, option?.value]
                      : filters?.eligibility?.filter(v => v !== option?.value);
                    onFilterChange('eligibility', newEligibility);
                  }}
                />
              ))}
            </div>
          </div>

          {/* Funding Type */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-foreground mb-3">
              Funding Type
            </label>
            <div className="space-y-2">
              {fundingOptions?.map((option) => (
                <Checkbox
                  key={option?.value}
                  label={option?.label}
                  checked={filters?.funding?.includes(option?.value)}
                  onChange={(e) => {
                    const newFunding = e?.target?.checked
                      ? [...filters?.funding, option?.value]
                      : filters?.funding?.filter(v => v !== option?.value);
                    onFilterChange('funding', newFunding);
                  }}
                />
              ))}
            </div>
          </div>

          {/* Verified Only */}
          <div className="mb-6">
            <Checkbox
              label="Show Verified Only"
              description="Display only community-verified opportunities"
              checked={filters?.verifiedOnly}
              onChange={(e) => onFilterChange('verifiedOnly', e?.target?.checked)}
            />
          </div>

          {/* Actions */}
          <div className="flex flex-col gap-2 pt-4 border-t border-border">
            <Button
              variant="outline"
              fullWidth
              iconName="RotateCcw"
              iconPosition="left"
              onClick={onClearFilters}
            >
              Clear All Filters
            </Button>
            <Button
              variant="default"
              fullWidth
              iconName="Bell"
              iconPosition="left"
            >
              Save Search Alert
            </Button>
          </div>
        </div>
      </aside>
    </>
  );
};

export default FilterSidebar;