import React from 'react';
import Icon from '../../../components/AppIcon';

const CategoryCard = ({ category, isActive, onClick }) => {
  const getCategoryIcon = (type) => {
    const icons = {
      all: 'Grid3x3',
      scholarships: 'GraduationCap',
      internships: 'Briefcase',
      jobs: 'Building2',
      competitions: 'Trophy',
      grants: 'DollarSign',
      fellowships: 'Award'
    };
    return icons?.[type] || 'Star';
  };

  return (
    <button
      onClick={onClick}
      className={`
        flex flex-col items-center gap-3 p-4 md:p-6 rounded-xl border-2 
        transition-all duration-300 min-w-[140px] md:min-w-[160px]
        ${isActive 
          ? 'border-primary bg-primary/5 shadow-md' 
          : 'border-border bg-card hover:border-primary/50 hover:shadow-sm'
        }
      `}
    >
      <div 
        className={`
          w-12 h-12 md:w-14 md:h-14 rounded-xl flex items-center justify-center
          transition-all duration-300
          ${isActive 
            ? 'bg-primary text-primary-foreground' 
            : 'bg-muted text-muted-foreground'
          }
        `}
      >
        <Icon name={getCategoryIcon(category?.type)} size={24} />
      </div>
      <div className="text-center">
        <h3 className={`text-sm md:text-base font-semibold mb-1 ${isActive ? 'text-primary' : 'text-foreground'}`}>
          {category?.label}
        </h3>
        <p className="text-xs text-muted-foreground">
          {category?.count} opportunities
        </p>
      </div>
      {category?.trending && (
        <span className="px-2 py-0.5 bg-accent text-accent-foreground text-xs rounded-full font-medium">
          Trending
        </span>
      )}
    </button>
  );
};

export default CategoryCard;