import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const OpportunityCard = ({ opportunity, onSave, onShare, isSaved, isLiked, onLike }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);

  const handleLikeClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsAnimating(true);
    if (onLike) onLike(opportunity.id);
    setTimeout(() => setIsAnimating(false), 450);
  };

  const isExpired = opportunity?.daysLeft !== null && opportunity?.daysLeft <= 0;
  const getDeadlineBadgeClass = (urgency) => {
    if (isExpired) return 'deadline-badge expired bg-gray-500/20 text-gray-500 border-gray-500/20';
    switch (urgency) {
      case 'urgent':
        return 'deadline-badge urgent';
      case 'warning':
        return 'deadline-badge warning';
      default:
        return 'deadline-badge safe';
    }
  };

  const getCategoryIcon = (category) => {
    const icons = {
      scholarships: 'GraduationCap',
      internships: 'Briefcase',
      jobs: 'Building2',
      competitions: 'Trophy',
      grants: 'DollarSign',
      fellowships: 'Award'
    };
    return icons?.[category] || 'Star';
  };

  return (
    <div className={cn("opportunity-card group flex flex-col h-full", isExpired && "opacity-80")}>
      {/* Header Image */}
      <div className="relative h-48 md:h-56 overflow-hidden rounded-xl mb-4">
        <Image
          src={opportunity?.image}
          alt={opportunity?.imageAlt}
          className={cn(
            "w-full h-full object-cover transition-transform duration-300 group-hover:scale-105",
            isExpired && "grayscale-[0.5]"
          )}
        />
        {/* Badges Container (Top Left) */}
        <div className="absolute top-3 left-3 flex flex-col gap-2 z-10">
          {opportunity?.trending && (
            <div className={cn(
              "text-accent-foreground px-3 py-1 rounded-full text-xs font-medium flex items-center gap-1 w-fit shadow-sm backdrop-blur-md bg-opacity-90",
              isExpired ? "bg-gray-400/50 text-gray-200 grayscale opacity-70" : "bg-accent"
            )}>
              <Icon name="TrendingUp" size={14} />
              Trending
            </div>
          )}
          {opportunity?.verified && (
            <div className={cn(
              "text-white px-3 py-1 rounded-full text-xs font-medium flex items-center gap-1 w-fit shadow-sm backdrop-blur-md",
              isExpired ? "bg-gray-400/50 text-gray-200 grayscale opacity-70" : "bg-emerald-500"
            )}>
              <Icon name="BadgeCheck" size={14} />
              Verified
            </div>
          )}
        </div>

        {/* Save/Bookmark Button (Top Right) */}
        <button
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            if (!isExpired) onSave(opportunity.id);
          }}
          className={cn(
            "absolute top-3 right-3 p-2 rounded-full transition-all duration-300 z-10 shadow-lg backdrop-blur-md border border-white/20",
            isSaved ? 'bg-[var(--color-accent)] text-white' : 'bg-black/40 text-white hover:bg-black/60',
            isExpired && "grayscale opacity-70 cursor-not-allowed"
          )}
          title={isExpired ? "Cannot save expired opportunity" : (isSaved ? "Unsave opportunity" : "Save opportunity")}
          disabled={isExpired}
        >
          <Icon name="Bookmark" size={18} fill={isSaved ? "currentColor" : "none"} />
        </button>

        {opportunity?.type && (
          <div className="absolute bottom-3 left-3">
            <span className={cn(
              "inline-block px-3 py-1 backdrop-blur-md text-white text-[10px] font-bold rounded-full border border-white/20 uppercase tracking-wider",
              isExpired ? "bg-gray-500/40" : "bg-black/60"
            )}>
              {opportunity?.type}
            </span>
          </div>
        )}
      </div>

      {/* Content */}
      <div className="space-y-3 flex-1 flex flex-col">
        {/* Category & Location */}
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Icon name={getCategoryIcon(opportunity?.category)} size={16} />
            <span className="capitalize">{opportunity?.category}</span>
          </div>
          <div className="flex items-center gap-1 text-sm text-muted-foreground">
            <Icon name="MapPin" size={14} />
            <span className="line-clamp-1">{opportunity?.location || 'Remote'}</span>
          </div>
        </div>

        {/* Stipend / Funding */}
        {opportunity?.stipend && (
          <div className={cn(
            "flex items-center gap-2 text-xs font-medium px-2 py-1 rounded w-fit",
            isExpired
              ? "text-gray-500 bg-gray-100 dark:bg-gray-800/50"
              : "text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20"
          )}>
            <Icon name="DollarSign" size={12} />
            <span>{opportunity?.stipend}</span>
          </div>
        )}

        {/* Title */}
        <Link to={`/opportunity-detail/${opportunity?.id}`} className="block">
          <h3 className={cn(
            "text-lg md:text-xl font-bold transition-colors line-clamp-2 leading-snug",
            isExpired ? "text-gray-500" : "text-primary group-hover:text-brand-blue"
          )}>
            {opportunity?.title}
          </h3>
        </Link>

        {/* Description & Deadline */}
        <p className="text-sm text-muted-foreground line-clamp-2">
          {opportunity?.shortDescription}
        </p>

        <div className="flex items-center justify-between pt-2 mt-auto">
          <span className={getDeadlineBadgeClass(opportunity?.urgency)}>
            <Icon name={isExpired ? "AlertCircle" : "Clock"} size={12} />
            {isExpired ? "Expired" : (opportunity?.daysLeft === null ? (opportunity?.deadline || "No Deadline") : `${opportunity?.daysLeft} days left`)}
          </span>

          {/* Social Stats */}
          <div className="flex items-center gap-3">
            <button
              onClick={(e) => {
                if (!isExpired) handleLikeClick(e);
                else {
                  e.preventDefault();
                  e.stopPropagation();
                }
              }}
              className={cn(
                "relative flex items-center gap-1 text-xs transition-all heart-hover",
                isAnimating ? 'animate-heart-pop' : '',
                isLiked ? 'text-red-500 font-bold scale-110' : 'text-muted-foreground hover:text-red-500',
                isExpired && "opacity-50 grayscale cursor-not-allowed"
              )}
              title={isExpired ? "Cannot like expired opportunity" : "Love this opportunity"}
              disabled={isExpired}
            >
              {isAnimating && (
                <>
                  <span className="heart-particle animate-ribbon bg-rose-500" style={{ '--burst-transform': 'translate(-200%, -200%)', '--burst-rotate': '-45deg' }}></span>
                  <span className="heart-particle animate-ribbon bg-blue-500" style={{ '--burst-transform': 'translate(100%, -250%)', '--burst-rotate': '10deg' }}></span>
                  <span className="heart-particle animate-ribbon bg-amber-500" style={{ '--burst-transform': 'translate(200%, -150%)', '--burst-rotate': '45deg' }}></span>
                  <span className="heart-particle animate-ribbon bg-emerald-500" style={{ '--burst-transform': 'translate(-150%, 100%)', '--burst-rotate': '-120deg' }}></span>
                  <span className="heart-particle animate-ribbon bg-purple-500" style={{ '--burst-transform': 'translate(0%, 200%)', '--burst-rotate': '0deg' }}></span>
                </>
              )}
              <Icon name="Heart" size={14} fill={isLiked ? "currentColor" : "none"} />
              <span>{opportunity?.likes_count || 0}</span>
            </button>
            <div className="flex items-center gap-1 text-xs text-muted-foreground">
              <Icon name="Users" size={14} />
              <span>{opportunity?.applicants?.toLocaleString()}</span>
            </div>
          </div>
        </div>

        {/* CTA */}
        <div className="pt-2">
          <Link to={`/opportunity-detail/${opportunity?.id}`} className="block">
            <Button
              variant="default"
              fullWidth
              iconName="ExternalLink"
              iconPosition="right"
              size="sm"
            >
              View Details
            </Button>
          </Link>
        </div>
      </div>
    </div>
  );
};

export default OpportunityCard;